from pathlib import Path
import json, hashlib
P=Path(__file__).resolve().parent;R=P.parents[1]
def edit(relative, old, new):
    p=R/relative;s=p.read_text(encoding='utf-8');assert s.count(old)==1,(relative,old);p.write_text(s.replace(old,new),encoding='utf-8')
edit('scripts/branforth_npc.gd','movement_medium=="dry" and not helmet_equipped and goal=="hull-repair"','movement_medium=="dry" and goal=="hull-repair"')
edit('scripts/branforth_npc.gd','movement_medium!="dry" or helmet_equipped or goal!="hull-repair"','movement_medium!="dry" or goal!="hull-repair"')
edit('scripts/branforth_npc.gd','BUNK_SECONDS if not motion.is_empty() else 0.0,true):','BUNK_SECONDS if not motion.is_empty() else 0.0,true,true):')
edit('scripts/bill_npc.gd','helmet_ward := false) -> bool:', 'helmet_ward := false, helmet_hull := false) -> bool:')
edit('scripts/bill_npc.gd','helmet_ward and data.goal=="ward-repair" and data.active and data.stage==""','((helmet_ward and data.goal=="ward-repair") or (helmet_hull and data.goal=="hull-repair")) and data.active and data.stage==""')
edit('scripts/hull_repair.gd','actor.state="weld" if actor.movement_medium=="dry" and not actor.helmet_equipped else "repair"','actor.state="weld" if actor.movement_medium=="dry" and (not actor.helmet_equipped or actor.has_method("sync_hull_animation")) else "repair"')
edit('scripts/james_hull_resume.gd',' and (actor.goal=="ward-repair" or not actor.helmet_equipped)','')
edit('scripts/james_hull_resume.gd',' or (data.get("helmet_equipped",false) and data.get("goal","")!="ward-repair")','')
s=(R/'character/james-hull-lifecycle-v1/validate.gd').read_text(encoding='utf-8')
s=s.replace('res://character/james-hull-lifecycle-v1/','res://character/james-hull-helmet-v1/north/')
s=s.replace('game.Architects.advance_core(game,10)','game.Architects.advance_core(game,10)\n\tcheck(game.branforth_npc.set_helmet_equipped(true),"Worn helmet through supported API, not locker fitting")')
s=s.replace('actor.helmet_equipped=false','actor.helmet_equipped=true')
s=s.replace('player.frames','player.equipment_frames["diving-helmet"]')
s=s.replace('actor.action_elapsed())','actor.action_elapsed(),"diving-helmet")')
s=s.replace('"foot":[actor.foot.x,actor.foot.y]','"helmet":actor.helmet_equipped,"foot":[actor.foot.x,actor.foot.y],"footViewport":[(root.get_stretch_transform()*game.grid_view.get_global_transform_with_canvas()*(actor.foot*game.get_cell_size()/384.0)).x,(root.get_stretch_transform()*game.grid_view.get_global_transform_with_canvas()*(actor.foot*game.get_cell_size()/384.0)).y]')
s=s.replace('work_steps+=1','work_steps+=1\n\t\t\tcheck(actor.helmet_equipped,"Helmet retained during actual work")')
s=s.replace('check(actor.valid_branforth_snapshot(actor.snapshot()),"Actual lifecycle snapshot remains admissible")','check(actor.valid_branforth_snapshot(actor.snapshot()),"Actual lifecycle snapshot remains admissible")\n\t\t\tif failures>0:quit(2);return')
s=s.replace('OUT+"validate.gd.uid"','"res://character/james-hull-helmet-v1/north.gd.uid"')
s=s.replace('JAMES HULL LIFECYCLE:','JAMES HULL HELMET NORTH:')
(P/'north.gd').write_text(s,encoding='utf-8');(P/'north').mkdir(exist_ok=True)
s=(R/'character/james-hull-cardinal-v1/validate.gd').read_text(encoding='utf-8')
s=s.replace('res://character/james-hull-lifecycle-v1/validate.gd','res://character/james-hull-helmet-v1/north.gd')
s=s.replace('res://character/james-hull-cardinal-v1/','res://character/james-hull-helmet-v1/cardinal/')
s=s.replace('RESULT+"access-probe-evidence.json"','"res://character/james-hull-cardinal-v1/access-probe-evidence.json"')
s=s.replace('actor.helmet_equipped=false','actor.helmet_equipped=true')
s=s.replace('game.grid_view.branforth_player.frames','game.grid_view.branforth_player.equipment_frames["diving-helmet"]')
s=s.replace('work_steps+=1;','work_steps+=1;check(actor.helmet_equipped,"Helmet retained in paid cardinal work");')
s=s.replace('check(actor.valid_branforth_snapshot(actor.snapshot()),"Cardinal ordinary snapshot admitted")','check(actor.valid_branforth_snapshot(actor.snapshot()),"Cardinal ordinary snapshot admitted")\n\t\t\tif failures>0:quit(2);return')
s=s.replace('RESULT+"validate.gd.uid"','"res://character/james-hull-helmet-v1/cardinal.gd.uid"')
s=s.replace('JAMES CARDINAL:','JAMES HULL HELMET CARDINAL:')
(P/'cardinal.gd').write_text(s,encoding='utf-8');(P/'cardinal').mkdir(exist_ok=True)
(P/'bill_compat.gd').write_text('extends "res://tests/test_hull_repair.gd"\n',encoding='utf-8')
files=['scripts/branforth_npc.gd','scripts/bill_npc.gd','scripts/hull_repair.gd','scripts/james_hull_resume.gd','scripts/james_hull_return.gd','scripts/james_construction_motion.gd','scripts/grid_canvas.gd','scripts/station_effects.gd','character/james-torch-material-residue-v2/bare-manifest.json','character/james-torch-material-residue-v2/helmet-manifest.json']
(P/'runtime-input-before.json').write_text(json.dumps({f:hashlib.sha256((R/f).read_bytes()).hexdigest() for f in files},indent=2)+'\n',encoding='utf-8')
print('Narrow James dry helmet Hull controller/admission and North/cardinal fixtures prepared')
